import os
import shutil

from pyspark.errors import PySparkException
from pyspark.sql import functions as F


def can_load(batch):
    # Checks that a day's batch can be written, before the load writes it.
    try:
        batch.count()
        return True
    except PySparkException:
        return False


def solve(shipment_events):
    path = "/tmp/tracking/events"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty table on every run
    digits = F.substring("event_id", 2, 20)  # the id without its first letter: "E0000009" -> "0000009"
    typed = shipment_events.select("event_id", "shipment_id", "load_date", digits.cast("int").alias("event_no"))
    days = sorted(row["load_date"] for row in shipment_events.select("load_date").distinct().collect())
    for day in days:
        batch = typed.filter(F.col("load_date") == day)
        if can_load(batch):
            batch.write.mode("append").parquet(path)
        # A day that can't be loaded is held back whole, for the carrier to send again.
    written = os.path.isdir(path) and any(name.endswith(".parquet") for name in os.listdir(path))
    if not written:  # no day was loaded
        return spark.createDataFrame([], typed.schema)
    return spark.read.parquet(path)
